from collections import defaultdict
def solve(rows):
    # rows: [{"month":"YYYY-MM","revenue":number}, ...]
    d=defaultdict(float)
    for r in rows: d[r["month"]]+=r["revenue"]
    months=sorted(d); out={}
    for i,m in enumerate(months):
      prev=d[months[i-1]] if i else None
      out[m]=None if prev in (None,0) else (d[m]-prev)/prev
    return out

def solve(X,y):
    import numpy as np
    X=np.asarray(X,dtype=float); y=np.asarray(y,dtype=float)
    return (np.linalg.pinv(X.T@X)@X.T@y).tolist()

